import{c as e,Q as r,j as n,m as d}from"./chunks/framework.BXc4yaFE.js";const y=JSON.parse('{"title":"Harness 實作有效性與 ROI 評估 — 12-unit fan-out + 落地計畫","description":"","frontmatter":{"title":"Harness 實作有效性與 ROI 評估 — 12-unit fan-out + 落地計畫","date":"2026-06-18T00:00:00.000Z","status":"complete","caveat":"byte 節省為各 unit 字元估算（±15%），實作以 wc -c 實測為準；每 cycle 後重量測","method":"12-unit dynamic-workflow fan-out（researcher，context isolation，3 批 ≤4）→ 主對話親驗（grep/wc/ls）→ fable-pilot anti-hack 紀律","scope":"評估 2026-06-18-harness-derivation-deep-research §7 四候選 + autoload byte 優化；實作範圍限 .claude/ + CLAUDE.md","type":"research","verification":"親驗 HARNESS-CARD 存在(8049B)、AGENTS.md 存在、CJK→英文+32%byte、8 個 ref 目標存在、gate 腳本齊備"},"headers":[],"relativePath":"research/reports/2026-06-18-harness-implementation-roi-eval.md","filePath":"research/reports/2026-06-18-harness-implementation-roi-eval.md","lastUpdated":1785909234000}'),a={name:"research/reports/2026-06-18-harness-implementation-roi-eval.md"};function s(l,t,o,i,c,g){return r(),n("div",null,[...t[0]||(t[0]=[d('<h1 id="harness-實作有效性與-roi-評估" tabindex="-1">Harness 實作有效性與 ROI 評估 <a class="header-anchor" href="#harness-實作有效性與-roi-評估" aria-label="Permalink to &quot;Harness 實作有效性與 ROI 評估&quot;">​</a></h1><blockquote><p><strong>TLDR</strong>：對「上一份報告 §7 的 4 個演化候選 + autoload byte 優化」做 12-unit fan-out ROI 評估。結論：<strong>§7 四候選全部 DEFER/DROP</strong>（B1 缺 eval 歷史前置；B2 HarnessCard <strong>已存在</strong>、報告 gap 過期；B3 白盒 99.6% 黑盒 API 不可達；B4 pilot 模式已覆蓋 70% 且違反「不為未來鋪設」）。唯一高 ROI、in-scope、低風險、使用者明確要求的實作 = <strong>autoload byte 優化</strong>（現 18,990B，距 19,000 審視線僅 10B）。關鍵策略修正：<strong>CJK→英文省 token 但 +32% byte</strong>（canonical 單位是 byte），故正確降法 = <strong>刪冗餘/修辭 + 下沉既有 refs</strong>，非翻譯。保守可降 ~2,600–3,700B → 目標 ≤17,000B（緩衝 ~2,000B）。</p></blockquote><hr><h2 id="_0-方法與驗證" tabindex="-1">0. 方法與驗證 <a class="header-anchor" href="#_0-方法與驗證" aria-label="Permalink to &quot;0. 方法與驗證&quot;">​</a></h2><p>12 個 researcher sub-agent 並行（3 批，每批 ≤4，遵 fan-out 上限），每個產出一張 ROI Card。主對話親驗關鍵發現（防 agentic-laziness，承上一 session Cluster-E 教訓）：</p><table tabindex="0"><thead><tr><th>親驗項</th><th>結果</th></tr></thead><tbody><tr><td>HARNESS-CARD.md 是否存在（B2）</td><td>✅ <code>research/agent-harness/HARNESS-CARD.md</code> 8049B/82 行，8 欄齊全（2026-06-12）→ B2 報告 gap <strong>過期</strong></td></tr><tr><td>AGENTS.md 是否存在（U11 疑 bug）</td><td>✅ root 存在 → CLAUDE.md L2「Read AGENTS.md first」<strong>有效非 bug</strong>（推翻 U11 該點）</td></tr><tr><td>CJK byte vs token（U3）</td><td>✅ cjk-token-efficiency.md 親驗「英文省~20% token 但 +32% byte」→ 不翻譯</td></tr><tr><td>8 個下沉目標 refs 存在</td><td>✅ 全 OK（下沉前置通過）</td></tr><tr><td>gate 腳本</td><td>✅ healthcheck.sh / measure.sh 齊備</td></tr><tr><td>全 12 unit tool_uses</td><td>✅ 全 &gt;0（無杜撰）</td></tr></tbody></table><hr><h2 id="_1-roi-評估矩陣-12-unit-彙整" tabindex="-1">1. ROI 評估矩陣（12 unit 彙整） <a class="header-anchor" href="#_1-roi-評估矩陣-12-unit-彙整" aria-label="Permalink to &quot;1. ROI 評估矩陣（12 unit 彙整）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Unit</th><th>候選</th><th style="text-align:center;">In-scope</th><th style="text-align:center;">有效性</th><th>byte 影響</th><th style="text-align:center;">風險</th><th style="text-align:center;">Verdict</th></tr></thead><tbody><tr><td>U1</td><td>core.md 下沉/壓縮</td><td style="text-align:center;">✅</td><td style="text-align:center;">5/5</td><td><strong>−~2,200</strong></td><td style="text-align:center;">low-med</td><td style="text-align:center;"><strong>DO-NOW</strong></td></tr><tr><td>U2</td><td>subagent+context 下沉 refs</td><td style="text-align:center;">✅</td><td style="text-align:center;">4/5</td><td><strong>−~1,175</strong></td><td style="text-align:center;">low</td><td style="text-align:center;"><strong>DO-NOW</strong></td></tr><tr><td>U10</td><td>frontier 約束削減（B1/B5/B6）</td><td style="text-align:center;">✅</td><td style="text-align:center;">4/5</td><td><strong>−~290</strong></td><td style="text-align:center;">low</td><td style="text-align:center;"><strong>DO-NOW</strong></td></tr><tr><td>U9</td><td>lazy-load×caching 衝突</td><td style="text-align:center;">✅</td><td style="text-align:center;">3/5</td><td>0</td><td style="text-align:center;">none</td><td style="text-align:center;"><strong>DO-NOW</strong>（純澄清，關 TODO）</td></tr><tr><td>U4</td><td>跨檔去重</td><td style="text-align:center;">✅</td><td style="text-align:center;">3/5</td><td>−~150</td><td style="text-align:center;">low</td><td style="text-align:center;"><strong>DO-NOW</strong>（併入 U1/U2）</td></tr><tr><td>U3</td><td>CJK→英文</td><td style="text-align:center;">✅</td><td style="text-align:center;">1/5</td><td><strong>+byte!</strong></td><td style="text-align:center;">—</td><td style="text-align:center;"><strong>DROP</strong>（方向相反）</td></tr><tr><td>U11</td><td>CLAUDE.md/README 精簡</td><td style="text-align:center;">✅</td><td style="text-align:center;">2/5</td><td>−~35</td><td style="text-align:center;">med(快取)</td><td style="text-align:center;"><strong>DEFER</strong>（微利不值破快取；AGENTS.md 非 bug）</td></tr><tr><td>U5/B1</td><td>先驗過濾 gate</td><td style="text-align:center;">✅</td><td style="text-align:center;">2/5</td><td>0</td><td style="text-align:center;">—</td><td style="text-align:center;"><strong>DEFER</strong>（缺 ≥10 cycle eval 歷史；AHE 回歸預測 11.8%≈無資訊）</td></tr><tr><td>U6/B2</td><td>HarnessCard 化</td><td style="text-align:center;">✅</td><td style="text-align:center;">1/5</td><td>0</td><td style="text-align:center;">—</td><td style="text-align:center;"><strong>DROP</strong>（已存在；另建=雙版本 drift）</td></tr><tr><td>U7/B3</td><td>pre-LLM untrusted 過濾</td><td style="text-align:center;">✅</td><td style="text-align:center;">2/5</td><td>0</td><td style="text-align:center;">med(誤判)</td><td style="text-align:center;"><strong>DEFER</strong>（白盒 99.6% 黑盒不可達；shell regex 僅邊際）</td></tr><tr><td>U8/B4</td><td>variant routing 預備</td><td style="text-align:center;">✅</td><td style="text-align:center;">2/5</td><td>+byte</td><td style="text-align:center;">—</td><td style="text-align:center;"><strong>DROP</strong>（pilot 已覆蓋 70%；違反「不為未來鋪設」）</td></tr></tbody></table><hr><h2 id="_2-§7-四候選為何全部不實作-誠實歸因" tabindex="-1">2. §7 四候選為何全部不實作（誠實歸因） <a class="header-anchor" href="#_2-§7-四候選為何全部不實作-誠實歸因" aria-label="Permalink to &quot;2. §7 四候選為何全部不實作（誠實歸因）&quot;">​</a></h2><ul><li><strong>B1 先驗過濾 gate（DEFER）</strong>：HARBOR posterior chance constraint 需「歷史 eval 後驗分布」；workspace 僅 per-model baseline（15 trials, 2026-05-30），<strong>無 per-rule per-cycle eval 時序 log</strong>，建不出統計後驗。且 AHE 實測回歸預測精度 <strong>11.8% ≈ 無資訊</strong>——即使資料足，先驗過濾誤拒率也高。重評前置：累積 ≥10 cycle eval log。</li><li><strong>B2 HarnessCard 化（DROP）</strong>：<code>research/agent-harness/HARNESS-CARD.md</code> <strong>已存在</strong>且 8 欄完整、有 5 次 audit changelog。報告 §5「缺機器可讀 harness spec」為 2026-06-12 前的過期判斷。另建一份 = 雙版本 drift（比缺口更糟）。低成本替代：harness-design.md L26 補精確路徑。</li><li><strong>B3 pre-LLM 過濾（DEFER）</strong>：IPI-defense 99.6% 是<strong>白盒 MLP + hidden states</strong>；Claude Code 黑盒 API 拿不到 hidden states，退化為 shell regex（對 base64/語意偽裝/多語幾乎無效），且誤判會擋正常 WebFetch/MCP。有意義的低成本下一步是 <strong>data provenance 標籤</strong>（非字面掃描），列為未來。</li><li><strong>B4 variant routing（DROP）</strong>：<code>/fable-pilot</code>等 pilot 模式 + multi-mode router + path-scoped rules 已覆蓋 ~70% 任務型別路由；任務流分布偏移是<strong>單人 workspace 未觀察的遠期假設</strong>，預先鋪設違反 core.md PROPOSE「不為未來可能鋪設 / Rule of 3」。</li></ul><hr><h2 id="_3-落地計畫-do-now-按-≤1-規則檔-cycle-拆-cycle" tabindex="-1">3. 落地計畫（DO-NOW，按 ≤1 規則檔/cycle 拆 cycle） <a class="header-anchor" href="#_3-落地計畫-do-now-按-≤1-規則檔-cycle-拆-cycle" aria-label="Permalink to &quot;3. 落地計畫（DO-NOW，按 ≤1 規則檔/cycle 拆 cycle）&quot;">​</a></h2><blockquote><p>執行協議（U12）：每 cycle = 改 1 個 auto-load 規則檔（+ 對應 refs 不計數）。每 cycle 後：<code>wc -c</code> 六源重量測 + <code>bash scripts/healthcheck.sh</code>（FAIL=0）+ grep 驗下沉內容存在 refs + git diff 審 → atomic commit。回滾用 <code>git revert</code>。<strong>下沉=資訊保留於 refs 不寫 manifest；純刪檔才寫 manifest</strong>。</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:center;">Cycle</th><th>檔案</th><th>動作</th><th style="text-align:center;">預估 −byte</th><th>風險控制</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td>core.md</td><td>下沉(Framework-Integrity 去重/APPLY 不可逆清單→best-solution/長期記憶細節/Git 命令序列) + 壓縮(TEST static-offline/RECORD) + 刪修辭(B1)</td><td style="text-align:center;">~2,000</td><td>下沉前 grep 確認目標 ref 已含該內容；鐵律紅線清單禁動</td></tr><tr><td style="text-align:center;">2</td><td>output-discipline.md</td><td>U10 B5 填充語清單→一句、B6 禁用詞→縮指針</td><td style="text-align:center;">~230</td><td>frontier hyper-literalism 證據（Prompting Inversion −2.36pp）</td></tr><tr><td style="text-align:center;">3</td><td>subagent-strategy.md</td><td>下沉(模型 grid→model-selection-grid/Routines/Background 壓縮/Dynamic 緊縮)</td><td style="text-align:center;">~600</td><td>Agent Input Security 紅線禁動</td></tr><tr><td style="text-align:center;">4</td><td>context-management.md</td><td>下沉(Compact hint→post-compact-checklist/Cache 健康→cache-health-metrics)</td><td style="text-align:center;">~350</td><td>Mid-session 禁止三條 + Token Budget 數字紅線禁動</td></tr><tr><td style="text-align:center;">—</td><td>文件衛生</td><td>U9 報告 §4 關 TODO(conflict)；B2 修報告 §5 過期 gap + harness-design L26 補 HARNESS-CARD 路徑</td><td style="text-align:center;">0</td><td>research/ 記錄誠實，非 harness 行為變更</td></tr></tbody></table><p><strong>目標</strong>：18,990 → <strong>≤17,000</strong>（緩衝 ~2,000B）；若各 cycle 乾淨可續推向 ~16,000。</p><h3 id="紅線-絕不動-跨-unit-共識" tabindex="-1">紅線（絕不動，跨 unit 共識） <a class="header-anchor" href="#紅線-絕不動-跨-unit-共識" aria-label="Permalink to &quot;紅線（絕不動，跨 unit 共識）&quot;">​</a></h3><p>語言繁中規則 · 生產安全紅線 · OBSERVE 先讀+on-rails · <strong>unverified_success 閘門</strong> · 不可逆操作列舉觸發句 · eval 回歸 ≥5pp→revert · git <code>-A</code> 禁用 · 前5/後5 行展示 · Token Budget 數字 · Agent Input Security · RECORD Checkpoint 句。</p><blockquote><p>二分原則（U10）：<strong>驗證閘門/安全紅線 = 留</strong>；<strong>為弱模型寫的修辭/枚舉補丁 = 可刪</strong>（core.md §Framework Integrity 自述「為弱模型寫的行為補丁該刪，驗證閘門該留」）。</p></blockquote><hr><h2 id="_4-後續-記錄不實作" tabindex="-1">4. 後續（記錄不實作） <a class="header-anchor" href="#_4-後續-記錄不實作" aria-label="Permalink to &quot;4. 後續（記錄不實作）&quot;">​</a></h2><ol><li>data provenance 標籤（B3 低成本替代，外部輸入來源標記）— 待 OBSERVE 階段識別需求。</li><li>先驗過濾 gate（B1）— 待累積 ≥10 cycle eval log 後重評。</li><li>variant routing（B4）— 待實際觀察到同任務型別 ≥3 次需手動指定同 skill 才升級。</li></ol>',23)])])}const u=e(a,[["render",s]]);export{y as __pageData,u as default};
